from __future__ import absolute_import

import time

from taf.selenium.gnb.oam.coam.vdu.pages.common_page import CommonPage
from taf.selenium.gnb.oam.coam.vdu.pages.panels.navigation import NavigationPanel
from taf.selenium.gnb.oam.coam.vdu.pages.panels.view import ViewPanel


class BtsStatus(CommonPage):
    """
    The class corresponding to bts status page on selenium coam vdu webem, all operations under bts status
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Radio Modules Status": RadioModulesStatusPage(driver, version),
                                   "Site View": SiteViewStatusPage(driver, version),
                                   "Site Properties": SitePropertiesStatusPage(driver, version),
                                   "ALD Status": ALDStatusPage(driver, version),
                                   "Cells Status": CellsStatusPage(driver, version)}
        super(BtsStatus, self).__init__(driver, version, self._instance_dict)


class RadioModulesStatusPage(object):
    """
    All operations on Radio Modules Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'Radio Modules Status']

    def __init__(self, driver, version):
        self._navigation_panel = RadioModulesStatusPageNavigationPanel(driver, version)
        self._view_panel = RadioModulesStatusPageViewPanel(driver, version)

    def get_radio_status_info(self, radio_module, timeout):
        """
        Method for Radio Modules Status

        :return: dict, specific information of Radio Modules
        """
        return self._view_panel.get_radio_status_info(radio_module, timeout)


class RadioModulesStatusPageNavigationPanel(NavigationPanel):
    pass


class RadioModulesStatusPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(RadioModulesStatusPageViewPanel, self).__init__(driver, version)

    def get_radio_status_info(self, radio_module, timeout):
        """
        Method for getting Radio Modules Status after mouse hovering on the Radio Module

        :param radio_module: str, Radio name , default RMOD-1
        :param timeout: int, timeout for the element be available to click

        :return: dict, specific information of DUs or Cells or VMs accordingly
        """
        self.wait_for_visibility(self.locator.RADIO_MODULES_XPATH.format(radio_module), timeout)
        self.perform_element_hover(self.locator.RADIO_MODULES_XPATH.format(radio_module), timeout)
        return self._parse_radio_info()

    def _parse_radio_info(self):
        """
        This keyword is for getting all the details of Radio from tool tip and parse it in to dict


        :return: dict of information collected for Radio module
        """
        radio_modules_status = {}
        for item in self.get_text_from_all_matching_elements(self.locator.RADIO_MODULES_STATUS_INFO_XPATH):
            radio_modules_status.update({item.split(":")[0].strip(): item.split(":")[-1].strip()})
        return radio_modules_status


