class SiteViewStatusPageNavigationPanel(NavigationPanel):
    pass


class SiteViewStatusPageViewPanel(RadioModulesStatusPageViewPanel):
    def __init__(self, driver, version):
        super(SiteViewStatusPageViewPanel, self).__init__(driver, version)

    def get_pod_status_info(self, pod_name, timeout=60):
        """
        Keyword for getting pod status information under Site View page

        :param pod_name: str, pod name e.g: "po-cran1-oamcp-0" or "po-cran1-up-0"
        :param timeout: int, timeout for the element be available to click

        :return: dict, specific information about pod name
        """
        self.wait_for_visibility(self.locator.SITE_VIEW_MODULE_XPATH.format(pod_name), timeout)
        self.perform_element_hover(self.locator.SITE_VIEW_MODULE_XPATH.format(pod_name), timeout)
        return self._parse_radio_info()


class SitePropertiesStatusPage(object):
    """
    All operations on vdu site properties modules status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'Site Properties']

    def __init__(self, driver, version):
        self._navigation_panel = SitePropertiesStatusPageNavigationPanel(driver, version)
        self._view_panel = SitePropertiesStatusPageViewPanel(driver, version)

    def get_vdu_site_properties_info(self, timeout):
        """
        :param timeout: int, timeout for the element be available to click

        Method for Site Properties Module Status

        :return: dict, specific information about vdu site properties
        """
        return self._view_panel.get_vdu_site_properties_info(timeout=timeout)


class SitePropertiesStatusPageNavigationPanel(NavigationPanel):
    pass


class SitePropertiesStatusPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(SitePropertiesStatusPageViewPanel, self).__init__(driver, version)

    def _get_vdu_site_properties(self, vdu_site_info, timeout=60):
        vdu_gnb_properties = {}
        self.click_enabled_element(self.locator.VDU_STATUS_PATH, timeout)
        param_info = len(
            self._driver.find_elements_by_xpath(self.locator.VDU_SITE_PROPERTIES_LENGTH.format(vdu_site_info)))
        for row in range(1, param_info + 1):
            vdu_properties_info = self.get_text_from_all_matching_elements(
                self.locator.VDU_MATCH_XPATH.format(vdu_site_info, row))
            vdu_gnb_properties.update({vdu_properties_info[i].replace(',', ':'): vdu_properties_info[i + 1] for i in
                                       range(0, len(vdu_properties_info), 2)})
        return vdu_gnb_properties

    def _get_vdu_gnb_ip_addr_info(self, vdu_site_info, timeout=60):
        gnb_ip_addr = []
        self.click_enabled_element(self.locator.VDU_STATUS_PATH, timeout)
        param_info = len(
            self._driver.find_elements_by_xpath(self.locator.VDU_SITE_PROPERTIES_LENGTH.format(vdu_site_info)))
        for row in range(1, param_info):
            key_list = self.get_fields_info_from_row(self.locator.VDU_IP_ADDR_XPATH, timeout)
            value_list = self.get_fields_info_from_row(self.locator.VDU_MATCH_XPATH.format(vdu_site_info, row), timeout)
            vdu_gnb_ip_addr = dict(zip(key_list, value_list))
            key_list_new = list(vdu_gnb_ip_addr.values())
            del vdu_gnb_ip_addr['']
            vdu_gnb_ip_addr_info = key_list_new[0], vdu_gnb_ip_addr
            gnb_ip_addr.append(vdu_gnb_ip_addr_info)
        return dict(gnb_ip_addr)

    def get_vdu_site_properties_info(self, timeout=60):
        vdu_site_list = [self.locator.VDU_GNB_PROPERTIES_NAME, self.locator.VDU_GNB_STATE_NAME,
                         self.locator.VDU_GNB_IP_ADDRESS_NAME, self.locator.EXTERNAL_IP_ADDRESS_NAME]
        vdu_site_info = {}
        for i in vdu_site_list:
            vdu_name = self.wait_for_enable(i).text
            if i == self.locator.VDU_GNB_PROPERTIES_NAME:
                vdu_site_info[vdu_name] = self._get_vdu_site_properties(vdu_site_info=self.locator.VDU_GNB_PROPERTIES,
                                                                        timeout=timeout)
            elif i == self.locator.VDU_GNB_STATE_NAME:
                vdu_site_info[vdu_name] = self._get_vdu_site_properties(vdu_site_info=self.locator.VDU_GNB_STATE,
                                                                        timeout=timeout)
            elif i == self.locator.VDU_GNB_IP_ADDRESS_NAME:
                vdu_site_info[vdu_name] = self._get_vdu_gnb_ip_addr_info(vdu_site_info=self.locator.VDU_GNB_IP_ADDRESS,
                                                                         timeout=timeout)
            else:
                vdu_site_info[vdu_name] = self._get_vdu_site_properties(vdu_site_info=self.locator.EXTERNAL_IP_ADDRESS,
                                                                        timeout=timeout)
        return vdu_site_info


class ALDStatusPage(object):
    """
    All operations on vdu ALD Status properties modules status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'ALD Status']

    def __init__(self, driver, version):
        self._view_panel = ALDStatusPageViewPanel(driver, version)

    def export_ret_configuration(self, timeout):
        self._view_panel.export_ret_configuration(timeout)

    def export_rae_configuration(self, timeout):
        self._view_panel.export_rae_configuration(timeout)

    def upload_ret_configuration_file(self, ald, ret, configuration_file_path, timeout):
        return self._view_panel.upload_ret_configuration_file(ald, ret, configuration_file_path, timeout)

    def upload_rae_configuration_file(self, ald, ret, configuration_file_path, timeout):
        return self._view_panel.upload_rae_configuration_file(ald, ret, configuration_file_path, timeout)


class ALDStatusPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(ALDStatusPageViewPanel, self).__init__(driver, version)

    def export_ret_configuration(self, timeout):
        self.click_enabled_element(self.locator.RET_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.EXPORT_BUTTON, timeout)

    def export_rae_configuration(self, timeout):
        self.click_enabled_element(self.locator.RAE_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.EXPORT_BUTTON, timeout)

    def upload_ret_configuration_file(self, ald_id, ret_id, configuration_file_path, timeout):
        self.click_enabled_element(self.locator.RET_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.ALD_FILTER.format('ret'), timeout)
        self.insert_text_to_enable_element(self.locator.ALD_ID_INPUT, ald_id, timeout)
        self.insert_text_to_enable_element(self.locator.RETU_ID_INPUT, ret_id, timeout)
        self.click_enabled_element(self.locator.RET_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.UPLOAD_RTE_CONFIGURATION_BUTTON, timeout)
        self.click_enabled_element(self.locator.UPLOAD_RET_CONFIGURATION_XPATH, timeout)
        self.upload(self.locator.LOAD_CONFIGURATION_FILE_XPATH, configuration_file_path, timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("upload configuration file started"), timeout=10)
        self.wait_for_invisibility(self.locator.TOAST_MESSAGE.format("upload configuration file started"), timeout=10)
        time.sleep(2)
        return self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout)

    def upload_rae_configuration_file(self, ald_id, rae_id, configuration_file_path, timeout):
        self.click_enabled_element(self.locator.RAE_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.ALD_FILTER.format('rae'), timeout)
        self.insert_text_to_enable_element(self.locator.ALD_ID_INPUT, ald_id, timeout)
        self.insert_text_to_enable_element(self.locator.RAEU_ID_INPUT, rae_id, timeout)
        self.click_enabled_element(self.locator.RAE_STATUS_VIEW, timeout)
        self.click_enabled_element(self.locator.UPLOAD_RAE_CONFIGURATION_BUTTON, timeout)
        self.click_enabled_element(self.locator.UPLOAD_WEIGHT_FACTOR_XPATH, timeout)
        self.upload(self.locator.LOAD_CONFIGURATION_FILE_XPATH, configuration_file_path, timeout)
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("upload weight factor file operation started"),
                                 timeout=10)
        self.wait_for_invisibility(self.locator.TOAST_MESSAGE.format("upload weight factor file operation started"),
                                   timeout=10)
        time.sleep(2)
        return self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout)


class CellsStatusPage(object):
    """
    All operations on Cells Modules Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'Cells Status']

    def __init__(self, driver, version):
        self._navigation_panel = CellsStatusPageNavigationPanel(driver, version)
        self._view_panel = CellsStatusPageViewPanel(driver, version)

    def block_cell(self, object_name, timeout):
        """
        This keyword will block the given cell object

        :param object_name: str, cell object that needs to be blocked, default value is 'NRCELL-1'
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the cell block 'cell block operation finished' or 'cell block  operation failed'
        """
        return self._view_panel.block_cell(object_name, timeout)

    def unblock_cell(self, object_name, timeout):
        """
        This keyword will unblock the given cell object

        :param object_name: str, cell object that needs to be unblocked, default value is 'NRCELL-1'
        :param timeout: int, timeout for the element be available to click

        :return: str, Status of the cell unblock 'cell unblock operation finished' or 'cell unblock  operation failed'
        """
        return self._view_panel.unblock_cell(object_name, timeout)


class CellsStatusPageNavigationPanel(NavigationPanel):
    pass


class CellsStatusPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(CellsStatusPageViewPanel, self).__init__(driver, version)

    def perform_operation(self, object_name, operation_type, timeout):
        operation_mapping = {
            'block': (
                '{} block operation started'.format(object_name),
                '{} block operation finished'.format(object_name)),
            'unblock': (
                '{} unblock operation started'.format(object_name),
                '{} unblock operation finished'.format(object_name))
        }

        operation_start_msg, operation_finish_msg = operation_mapping[operation_type]

        self.click_enabled_element(self.locator.CELL_STATUS_MODULE_XPATH.format(object_name), timeout)
        self.click_enabled_element(self.locator.CELL_VERTICAL_DOTS_XPATH, timeout)

        if operation_type == 'block':
            self.click_enabled_element(self.locator.BLOCK_CELL_XPATH, timeout)
        elif operation_type == 'unblock':
            self.click_enabled_element(self.locator.UNBLOCK_CELL_XPATH, timeout)

        time.sleep(1)
        self.click_enabled_element(self.locator.BLOCK_OK_BUTTON_XPATH, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(operation_start_msg), timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format(operation_finish_msg), timeout)

        return self.get_text(self.locator.OPERATION_STATUS_LABEL_XPATH, timeout)

    def block_cell(self, object_name, timeout):
        return self.perform_operation(object_name, 'block', timeout)

    def unblock_cell(self, object_name, timeout):
        return self.perform_operation(object_name, 'unblock', timeout)
